<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $roles = Illuminate\Support\Facades\DB::table("role_permissions")->join("roles", "roles.id", "=", "role_permissions.role_id")->join("permissions", "permissions.id", "=", "role_permissions.permission_id")->where("permissions.module_key", "finance")->whereIn("permissions.action_key", ["view", "create"])->select("roles.name as role", "permissions.action_key as action")->get(); foreach($roles as $r) { echo $r->role . " -> " . $r->action . "\n"; }
